import{_ as p,a0 as s,w as l,s as i,ao as m,I as a,x as o,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux中的more命令－逐頁顯示長文本文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中的more命令－逐頁顯示長文本文件 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中的more命令－逐頁顯示長文本文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中的more命令－逐頁顯示長文本文件 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Linux more Command - Display Long Text File Per page at a Time","title":"Linux中的more命令－逐頁顯示長文本文件","tag":"201403","desc":""},"relativePath":"201403/Linux more Command - Display Long Text File Per page at a Time.md","filePath":"[post].md"}'),d={name:"201403/Linux more Command - Display Long Text File Per page at a Time.md"};function g(c,e,h,x,u,_){const r=s("Link");return l(),i("div",null,[e[11]||(e[11]=m(`<h1 id="linux中的more命令-逐頁顯示長文本文件" tabindex="-1">Linux中的more命令－逐頁顯示長文本文件 <a class="header-anchor" href="#linux中的more命令-逐頁顯示長文本文件" aria-label="Permalink to “Linux中的more命令－逐頁顯示長文本文件”">​</a></h1><p>如果你已經習慣了在Linux系統上工作，那你一定會發現在Linux世界中存在着大量的文本文件。配置文件和日誌文件通常都採用文本格式。這些文件通常都有很長的內容，不能在一屏內全部顯示。所以在處理這種文件時，我們需要分頁顯示。這時我們可以用上<strong>more</strong>命令。</p><h3 id="more是幹嘛的" tabindex="-1">more是幹嘛的 <a class="header-anchor" href="#more是幹嘛的" aria-label="Permalink to “more是幹嘛的”">​</a></h3><p>more是一個用來分頁顯示大文本文件的命令，它默認是內置在各個Linux發行版中的。</p><h3 id="怎麼用more" tabindex="-1">怎麼用more <a class="header-anchor" href="#怎麼用more" aria-label="Permalink to “怎麼用more”">​</a></h3><p>使用more命令，只需要鍵入:</p><pre><code>$ more file_name
</code></pre><p>比如，我們想檢查/var/log目錄下的日誌文件syslog，只需要鍵入：</p><pre><code>$ more /var/log/syslog
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more.png" alt="more命令"></p><p>然後我們可以看到<strong>在屏幕左下角有個提示</strong>，告訴我們當前的顯示比例為0%。看上去這個文件相當大，所以第一頁是全部頁數的0%。使用空格鍵可以往下翻頁，然後就可以看到提示的百分比會增加。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_2.png" alt="Scroll page"></p><h3 id="限制每頁顯示的行數" tabindex="-1">限制每頁顯示的行數 <a class="header-anchor" href="#限制每頁顯示的行數" aria-label="Permalink to “限制每頁顯示的行數”">​</a></h3><p>在執行more命令的時候，它會佔用你終端窗口的全部空間用於顯示。但是你可以通過參數<strong>-數字</strong>來限制每頁顯示的行數。</p><p>例如，你希望每頁<strong>限制顯示12行</strong>，可以通過下面的命令：</p><pre><code>$ more -12 /var/log/syslog
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_12.png" alt="限制每頁顯示12行"></p><p>現在，你會看到每頁只顯示12行，在按下空格鍵後，就會翻頁顯示後面的12行。</p><h3 id="display-user-message" tabindex="-1">Display user message <a class="header-anchor" href="#display-user-message" aria-label="Permalink to “Display user message”">​</a></h3><p>我們知道，more命令會在顯示區域的左下角提示當前內容所佔的百分比。對於第一次使用more命令的人來説，他或她可能會想知道怎麼才能往下翻頁。為了避免這種情況，我們可以在執行時增加<strong>-d</strong>參數，這樣就會額外顯示一行用户信息“[<strong>按空格鍵繼續，‘q‘推出.</strong>]”</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_d1.png" alt="More with -d option"></p><p>如果用户按了<strong>‘空格‘或’q‘</strong>之外的按鍵，more會顯示一行幫助信息<strong>“ [按‘h’鍵查看提示。]”</strong></p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_d2.png" alt="More displaying help message"></p><p>如果按下h鍵，會顯示一個幫助信息：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_dh.png" alt="Display help"></p><p>一個有意思的指令是<strong>b</strong>按鈕，<strong>b按鈕允許你</strong>退回到前面的頁面。換句話説，b按鈕可以允許<strong>向前翻頁</strong>。</p><p>你可以通過左上角的<strong>...前1頁</strong>信息來確認當前顯示的是前面的頁面。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_back.png" alt="在more中往前翻頁"></p><h3 id="禁止滾動" tabindex="-1">禁止滾動 <a class="header-anchor" href="#禁止滾動" aria-label="Permalink to “禁止滾動”">​</a></h3><p>通過參數<strong>-c</strong>，more命令不會滾動頁面，而是直接清除之前的內容，替換為下一頁的內容。 With <strong>-c</strong> option, more will not scroll the page. It will clear the previous page and put the next page or lines there.</p><pre><code>$ more -10 -c lynis.log
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_c.png" alt="Suppress scroll"></p><p>如果按下空格鍵，下一頁會仍然有相同的大小。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_c2.png" alt="Suppress scroll"></p><h3 id="忽略多餘的空白行" tabindex="-1">忽略多餘的空白行 <a class="header-anchor" href="#忽略多餘的空白行" aria-label="Permalink to “忽略多餘的空白行”">​</a></h3><p>使用參數<strong>-s</strong>來忽略多餘的空白行，下面是個例子：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_s.png" alt="多個空白行的文件"></p><p>當我們增加參數<strong>-s</strong>後：</p><pre><code>$ more -s doc_30.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_s2.png" alt="忽略了多餘空白行"></p><h3 id="查找字符串" tabindex="-1">查找字符串 <a class="header-anchor" href="#查找字符串" aria-label="Permalink to “查找字符串”">​</a></h3><p>如果你的日誌文件非常大，那麼在其中查找你想要的字符串並不是那麼容易。more命令的查找功能可以幫你，通過參數<strong>+/string</strong>可以用來搜索字符串，找到的關鍵字會顯示在第一行。比如我們要在<strong>/var/logs/syslog</strong>文件中搜索“<strong>dhclient</strong>”，那more命令的格式：</p><pre><code>$ more +/dhclient /var/log/syslog
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_string.png" alt="查找字符串"></p><p>然後，如果要在文件中繼續搜索下一個，只需要按下<strong>/按鈕</strong>，後面跟有關鍵字dhclient。</p><h3 id="從指定行開始顯示" tabindex="-1">從指定行開始顯示 <a class="header-anchor" href="#從指定行開始顯示" aria-label="Permalink to “從指定行開始顯示”">​</a></h3><p>你也可以通過參數<strong>+數字</strong>來指定開始顯示的行，例如，我們有一個15行的文件：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_num1.png" alt="多行文件"></p><p>然後我們想從第5行開始顯示這個文件的內容，命令看起來會是這個樣子：</p><pre><code>$ more +5 doc_30.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_num2.png" alt="從指定行開始顯示"></p><h3 id="可以顯示二進制文件嗎" tabindex="-1">可以顯示二進制文件嗎? <a class="header-anchor" href="#可以顯示二進制文件嗎" aria-label="Permalink to “可以顯示二進制文件嗎?”">​</a></h3><p><strong>答案是不行</strong>. more命令會提示這樣的信息，例如：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_binary.png" alt="顯示二進制文件"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>more是一個用來查看文本文件的基礎工具，它不能用來顯示二進制文件。通常，我們可以通過命令<strong>man more</strong>或者<strong>more --help</strong>來獲取更多關於more怎麼使用的信息。</p><hr>`,57)),a("p",null,[e[1]||(e[1]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-command/linux-more-command/"},{default:n(()=>[...e[0]||(e[0]=[o("http://linoxide.com/linux-command/linux-more-command/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=o("譯者：",-1)),t(r,{href:"https://github.com/zpl1025"},{default:n(()=>[...e[2]||(e[2]=[o("zpl1025",-1)])]),_:1}),e[5]||(e[5]=o(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[o("LCTT",-1)])]),_:1}),e[9]||(e[9]=o(" 原創翻譯，",-1)),t(r,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[o("Linux中國",-1)])]),_:1}),e[10]||(e[10]=o(" 榮譽推出",-1))])])}const L=p(d,[["render",g]]);export{b as __pageData,L as default};
